export const getListAdsUrl = (params?: ListAdsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/ads?${stringifiedParams}` : `/api/ads`
}

/**
 * @summary Community advertisements
 */
export const listAds = async (params?: ListAdsParams, options?: Parameters<typeof customFetch>[1]): Promise<Advertisement[]> => {

  return customFetch<Advertisement[]>(getListAdsUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





